/**
 * Slack Node - Version 2.5
 * Discriminator: resource=reaction, operation=get
 */


interface Credentials {
  slackApi: CredentialReference;
  slackOAuth2Api: CredentialReference;
}

/** Get information about a channel */
export type SlackV25ReactionGetParams = {
  resource: 'reaction';
  operation: 'get';
  authentication?: 'accessToken' | 'oAuth2' | Expression<string>;
/**
 * The Slack channel to get the reactions from
 * @searchListMethod getChannels
 * @default {"mode":"list","value":""}
 */
    channelId?: { __rl: true; mode: 'list' | 'id' | 'url'; value: string; cachedResultName?: string };
/**
 * Timestamp of the message to add, get or remove
 */
    timestamp: number | Expression<number>;
};

export type SlackV25ReactionGetNode = {
  type: 'n8n-nodes-base.slack';
  version: 2.5;
  config: NodeConfig<SlackV25ReactionGetParams> & { credentials?: Credentials };
};